/**
 * ContentSafety — the one gate every Misar book (and any long text) passes
 * before anyone can download, sell or publish it.
 *
 * How to read this file:
 *   1. Word lists come first. Each list says where it came from.
 *   2. Then the class. Each method does ONE job and returns a list of problems.
 *   3. `checkBook()` runs every check. `checkIdea()` runs the cheap ones on a
 *      title + topic before any writing starts.
 *
 * Rules of this file:
 *   - No imports. No third-party libraries, APIs or AI models.
 *   - Plain words, short functions. If a function needs a long comment, split it.
 *   - Word lists are a floor, not a guarantee. A person still reviews every
 *     children's book before it is published.
 */

// ---------------------------------------------------------------------------
// 1. Types — what goes in and what comes out
// ---------------------------------------------------------------------------

/** Who the book is written for. Children get the strictest rules. */
export type Audience = "children" | "middle-grade" | "young-adult" | "adult";

/** block = cannot ship. fix = should be fixed before shipping. note = a person should look. */
export type Level = "block" | "fix" | "note";

/** One thing that is wrong, where it is, and how to fix it. */
export interface Problem {
  rule: string;
  level: Level;
  where: string;
  why: string;
  howToFix: string;
}

/** One chapter: a title and its text sections (markdown is fine). */
export interface ChapterToCheck {
  title: string;
  sections: readonly string[];
}

/** Everything we know about a book when we check it. */
export interface BookToCheck {
  title: string;
  subtitle?: string;
  author?: string;
  /** Who the book is for. Left out = "children": we always protect anyone under 18 unless told otherwise. */
  audience?: Audience;
  chapters: readonly ChapterToCheck[];
  /** Store listing text (sales page). */
  description?: string;
  /** Metadata markdown, as written by the marketing step. */
  metadata?: string;
  /** Keywords, if already split. Otherwise they are read from `metadata`. */
  keywords?: readonly string[];
  /** All words printed on the covers (front, back, spine). */
  coverText?: readonly string[];
  /** The ISBN the author owns. Any other ISBN in the book is blocked. */
  isbn?: string;
  /** True when an AI model wrote text or made images for this book. */
  aiGenerated?: boolean;
  /** What the store listing will declare about AI use. */
  aiDisclosure?: { text: boolean; images: boolean };
  /** Set when the book adapts a public-domain work. */
  publicDomain?: { sourceTitle: string; sourceText?: string };
}

/** The answer: one verdict, every problem, and a few simple numbers. */
export interface SafetyReport {
  verdict: "block" | "fix" | "pass";
  problems: Problem[];
  scores: {
    words: number;
    readingEase: number;
    aiWordsPer100: number;
  };
}

