// ---------------------------------------------------------------------------
// 3. The class
// ---------------------------------------------------------------------------

/** Extra switches for `checkText()`. */
export interface TextCheckOptions {
  /**
   * The text is an email or message template, so merge tags such as
   * `{{first_name}}` or `{{ name | default: "there" }}` are filled in later
   * and are not unfinished placeholders.
   */
  allowTemplateTags?: boolean;
}

/** A merge tag: a plain field name in double braces, with an optional `| filter`. */
const TEMPLATE_TAG = /\{\{\s*[\w.]+(?:\s*\|[^}]{0,40})?\s*\}\}/g;

/** Lists a team can grow at runtime with `addWords()` (for example a private slur list). */
export type WordListName = "sexual" | "minor" | "swear" | "hate" | "violence" | "drugs" | "selfHarm";

/** One paragraph of the book and where it lives. */
interface Paragraph {
  text: string;
  where: string;
}

export class ContentSafety {
  // ----- singleton: there is only ever one ContentSafety -----

  private static only: ContentSafety | null = null;

  /** Get the one shared ContentSafety. */
  static get(): ContentSafety {
    if (!ContentSafety.only) ContentSafety.only = new ContentSafety();
    return ContentSafety.only;
  }

  private readonly lists: Record<WordListName, string[]> = {
    sexual: [...SEXUAL_WORDS],
    minor: [...MINOR_WORDS],
    swear: [...SWEAR_WORDS],
    hate: [],
    violence: [...GRAPHIC_VIOLENCE_WORDS],
    drugs: [...DRUG_WORDS],
    selfHarm: [...SELF_HARM_WORDS],
  };

  private readonly patternCache = new Map<string, RegExp>();

  private constructor() {}

  // ----- public: the three things callers use -----

  /** Add words to a list (for example a private slur list, or test words). */
  addWords(list: WordListName, words: readonly string[]): void {
    for (const word of words) {
      const clean = this.makeTextComparable(word);
      if (clean && !this.lists[list].includes(clean)) this.lists[list].push(clean);
    }
  }

  /** Check any text: a chat reply, a post, an email, a prompt, a terminal screen. Protects children by default. */
  checkText(text: string, audience: Audience = DEFAULT_AUDIENCE, where = "text", options: TextCheckOptions = {}): SafetyReport {
    if (options.allowTemplateTags) text = text.replace(TEMPLATE_TAG, "name");
    const paragraphs = text.split(/\n\s*\n/).map((t) => t.trim()).filter(Boolean);
    const problems: Problem[] = [];
    paragraphs.forEach((t, i) => problems.push(...this.checkOneParagraph({ text: t, where: `${where}, part ${i + 1}` }, audience)));
    problems.push(...this.findHiddenWordsInArt(text, where, audience));
    problems.push(...this.findTooManyAiWords(text, where));
    return this.makeReport(problems, text);
  }

  /**
   * Harm rules only: child safety, grooming, dangerous instructions, hate,
   * wrong for the audience, ID and card numbers, hidden words and control characters.
   * No writing-quality rules, so drafts, prototypes and generation inputs
   * (a topic, a site someone builds for themselves) are not blocked for style.
   */
  checkForHarm(text: string, audience: Audience = DEFAULT_AUDIENCE, where = "text"): SafetyReport {
    const paragraphs = text.split(/\n\s*\n/).map((t) => t.trim()).filter(Boolean);
    const problems: Problem[] = [];
    paragraphs.forEach((t, i) => problems.push(...this.findHarmInParagraph(t, `${where}, part ${i + 1}`, audience)));
    problems.push(...this.findHiddenWordsInArt(text, where, audience));
    return this.makeReport(problems, text);
  }

  /** Make text safe to print in a terminal: removes colour codes, control characters and direction flips. */
  cleanForTerminal(text: string): string {
    return text.replace(TERMINAL_CODES, "").replace(DIRECTION_FLIPPERS, "").replace(CONTROL_CHARACTERS, "");
  }

  /**
   * Rough picture check. Code cannot see what a picture shows, so this only
   * raises a flag for a person to look: lots of skin-coloured or blood-red pixels.
   * Every picture for children must still be approved by a person.
   */
  checkImagePixels(image: { width: number; height: number; rgba: ArrayLike<number> }, audience: Audience = DEFAULT_AUDIENCE, where = "image"): SafetyReport {
    const { skin, blood } = this.countColourShares(image);
    const strict = audience !== "adult";
    const problems: Problem[] = [this.problem("image-human-review", "note", where,
      "Code cannot see what a picture shows.", "A person must look at this picture before it ships, especially for children.")];
    if (skin > 0.35) problems.push(this.problem("image-skin", strict ? "fix" : "note", where,
      `About ${Math.round(skin * 100)}% of the picture is skin-coloured. It may show bare skin.`, "A person must check the picture before it is used."));
    if (blood > 0.25) problems.push(this.problem("image-blood", strict ? "fix" : "note", where,
      `About ${Math.round(blood * 100)}% of the picture is blood red. It may show gore.`, "A person must check the picture before it is used."));
    return this.makeReport(problems, "");
  }

  /** Cheap check on a title and topic, before any writing starts. */
  checkIdea(title: string, topic: string, audience: Audience = DEFAULT_AUDIENCE): SafetyReport {
    const text = `${title}\n${topic}`;
    const where = "book idea (title and topic)";
    const problems = [
      ...this.findSexualContentNearMinors(text, where),
      ...this.findGroomingPatterns(text, where),
      ...this.findDangerousInstructions(text, where),
      ...this.findHateOrHarassment(text, where),
      ...this.findWrongForAudience(text, where, audience),
      ...this.findHiddenWordsInArt(text, where, audience),
      ...this.findHiddenControlCharacters(text, where),
    ];
    return this.makeReport(problems, text);
  }

  /** Full check of a finished book. Runs every rule. */
  checkBook(book: BookToCheck): SafetyReport {
    const audience = book.audience ?? DEFAULT_AUDIENCE;
    const paragraphs = this.splitIntoParagraphs(book);
    const allText = paragraphs.map((p) => p.text).join("\n\n");
    const problems: Problem[] = [];

    for (const p of paragraphs) problems.push(...this.checkOneParagraph(p, audience));
    problems.push(...this.findTooManyAiWords(allText));
    problems.push(...this.findRepeatedParagraphs(paragraphs));
    for (const chapter of book.chapters) problems.push(...this.checkOneChapter(chapter, audience));
    for (const chapter of book.chapters) problems.push(...this.findHiddenWordsInArt(chapter.sections.join("\n"), `chapter "${chapter.title}"`, audience));
    problems.push(...this.findListingProblems(book));
    problems.push(...this.findFakeIsbns(book));
    problems.push(...this.findMissingAiDisclosure(book));
    problems.push(...this.findPublicDomainProblems(book, allText));

    return this.makeReport(problems, allText);
  }

  // ----- step 1: safety rules that run on every paragraph -----

  /** The harm rules for one paragraph (no writing-quality rules). */
  private findHarmInParagraph(text: string, where: string, audience: Audience): Problem[] {
    return [
      ...this.findSexualContentNearMinors(text, where),
      ...this.findGroomingPatterns(text, where),
      ...this.findDangerousInstructions(text, where),
      ...this.findHateOrHarassment(text, where),
      ...this.findWrongForAudience(text, where, audience),
      ...this.findPersonalData(text, where),
      ...this.findHiddenControlCharacters(text, where),
    ];
  }

  /** All per-paragraph rules, in one place: harm first, then writing quality. */
  private checkOneParagraph(p: Paragraph, audience: Audience): Problem[] {
    return [
      ...this.findHarmInParagraph(p.text, p.where, audience),
      ...this.findChatbotLeftovers(p.text, p.where),
      ...this.findPlaceholderText(p.text, p.where),
      ...this.findClichesAndFiller(p.text, p.where),
      ...this.findUnprovenClaims(p.text, p.where),
    ];
  }

  /** Zero tolerance: any sexual word close to a word about a child. Always blocks. */
  private findSexualContentNearMinors(text: string, where: string): Problem[] {
    const words = this.splitIntoWords(this.markYoungAges(this.makeTextComparable(text)));
    const sexual = this.positionsOf(words, this.lists.sexual);
    const minor = this.positionsOf(words, this.lists.minor);
    const tooClose = sexual.some((s) => minor.some((m) => Math.abs(s - m) <= NEAR_WORDS));
    if (!tooClose) return [];
    return [this.problem("child-safety", "block", where,
      "Sexual words appear close to words about a child.",
      "Remove it. Sexual content involving minors is never allowed. If this is age-appropriate safety or health education, a human reviewer must approve it.")];
  }

  /** Zero tolerance: grooming language when a child is mentioned. Always blocks. */
  private findGroomingPatterns(text: string, where: string): Problem[] {
    const clean = this.markYoungAges(this.makeTextComparable(text));
    const mentionsChild = this.positionsOf(this.splitIntoWords(clean), this.lists.minor).length > 0;
    const groomingPhrase = GROOMING_PHRASES.find((phrase) => this.containsPhrase(clean, phrase));
    if (!mentionsChild || !groomingPhrase) return [];
    return [this.problem("child-safety-grooming", "block", where,
      `Grooming language ("${groomingPhrase}") appears near a mention of a child.`,
      "Remove it, or have a human reviewer confirm it is a clearly framed safety lesson for children.")];
  }

  /** Step-by-step instructions that can hurt people. Blocks for every audience. */
  private findDangerousInstructions(text: string, where: string): Problem[] {
    const hit = DANGEROUS_PATTERNS.find((pattern) => pattern.test(text));
    if (!hit) return [];
    return [this.problem("dangerous-instructions", "block", where,
      "Instructions for weapons, drugs, self-harm or harming children.",
      "Remove the instructions. Describe the danger without telling readers how to do it.")];
  }

  /** Calls for harm against a group, plus any words a team added to the hate list. */
  private findHateOrHarassment(text: string, where: string): Problem[] {
    const clean = this.makeTextComparable(text);
    const patternHit = HATE_PATTERNS.some((pattern) => pattern.test(clean));
    const wordHit = this.lists.hate.find((word) => this.containsPhrase(clean, word));
    if (!patternHit && !wordHit) return [];
    return [this.problem("hate", "block", where,
      "Text attacks or calls for harm against a group of people.",
      "Remove it. Quoting hate for history or education needs clear framing and human review.")];
  }

  /** Sex, gore, self-harm, drugs and swearing: blocked for kids, flagged for teens. */
  private findWrongForAudience(text: string, where: string, audience: Audience): Problem[] {
    if (audience === "adult") return [];
    const level: Level = audience === "young-adult" ? "fix" : "block";
    const clean = this.makeTextComparable(text);
    const checks: [WordListName, string][] = [
      ["sexual", "sexual content"], ["violence", "graphic violence"], ["selfHarm", "self-harm"],
      ["drugs", "drugs or alcohol"], ["swear", "swearing"],
    ];
    const problems: Problem[] = [];
    for (const [list, label] of checks) {
      const word = this.lists[list].find((w) => this.containsPhrase(clean, w));
      if (word) problems.push(this.problem(`audience-${list}`, level, where,
        `Contains ${label} ("${word}"), which does not fit a book for ${AUDIENCE_NAMES[audience]}.`,
        `Rewrite it for ${AUDIENCE_NAMES[audience]}. Only mark the book "adult" if it really is for adults.`));
    }
    return problems;
  }

  /** Real-looking personal data. Card and ID numbers block; emails and phones need a look. */
  private findPersonalData(text: string, where: string): Problem[] {
    const problems: Problem[] = [];
    if (/\b\d{3}-\d{2}-\d{4}\b/.test(text)) problems.push(this.problem("personal-data-id", "block", where,
      "Looks like a government ID number (SSN format).", "Remove it or replace it with an obviously fake example such as 000-00-0000."));
    if (this.findCardNumbers(text).length > 0) problems.push(this.problem("personal-data-card", "block", where,
      "Looks like a real payment card number.", "Remove it."));
    if (/[\w.+-]+@[\w-]+\.[\w.]+/.test(text)) problems.push(this.problem("personal-data-email", "note", where,
      "Contains an email address.", "Keep it only if it is the author's own public contact address."));
    if (/(?:\+\d{1,3}[\s.-]?)?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}\b/.test(text)) problems.push(this.problem("personal-data-phone", "note", where,
      "Contains a phone number.", "Keep it only if it is a public business number you are allowed to print."));
    return problems;
  }

  /** Words hidden in ASCII art: the first letters of each line, or rude keyboard pictures. */
  private findHiddenWordsInArt(text: string, where: string, audience: Audience): Problem[] {
    const problems: Problem[] = [];
    const firstLetters = this.firstLetterOfEachLine(text);
    const lists: WordListName[] = audience === "adult" ? ["hate"] : ["sexual", "swear", "hate", "drugs"];
    const hidden = lists.flatMap((list) => this.lists[list]).find((word) => word.length >= 4 && !word.includes(" ") && firstLetters.includes(word));
    if (hidden) problems.push(this.problem("hidden-word", audience === "adult" ? "fix" : "block", where,
      `The first letters of the lines spell "${hidden}".`, "Rewrite the lines so they don't spell it."));
    const art = RUDE_ASCII_ART.find((pattern) => pattern.test(text.replace(/\s+/g, " ")));
    if (art && audience !== "adult") problems.push(this.problem("rude-ascii-art", "block", where,
      "Contains a rude picture drawn with keyboard characters.", "Remove it."));
    return problems;
  }

  /** Terminal codes, control characters and direction flips can hide or fake text. Never allowed in content. */
  private findHiddenControlCharacters(text: string, where: string): Problem[] {
    const found = [TERMINAL_CODES, DIRECTION_FLIPPERS, CONTROL_CHARACTERS].some((pattern) => {
      pattern.lastIndex = 0;
      const hit = pattern.test(text);
      pattern.lastIndex = 0;
      return hit;
    });
    if (!found) return [];
    return [this.problem("hidden-control-characters", "block", where,
      "Contains hidden terminal codes, control characters or direction-flipping characters that can hide or fake text.",
      "Remove them. Use cleanForTerminal() before showing text in a terminal.")];
  }

  // ----- step 2: writing quality (anti-AI writing) -----

  /** Chatbot text pasted into the book. Always blocks: a reader must never see it. */
  private findChatbotLeftovers(text: string, where: string): Problem[] {
    const clean = this.makeTextComparable(text);
    const phrase = CHATBOT_LEFTOVERS.find((p) => this.containsPhrase(clean, p));
    if (!phrase) return [];
    return [this.problem("ai-chatbot-leftover", "block", where,
      `Chatbot text left in the book: "${phrase}".`, "Delete it and rewrite the sentence as the author.")];
  }

  /** Text that was meant to be filled in. Always blocks. */
  private findPlaceholderText(text: string, where: string): Problem[] {
    const hit = PLACEHOLDER_PATTERNS.find((pattern) => pattern.test(text));
    if (!hit) return [];
    return [this.problem("placeholder", "block", where,
      "Placeholder text was never filled in.", "Replace it with the real text.")];
  }

  /** Stock phrases and filler that make writing sound generated. */
  private findClichesAndFiller(text: string, where: string): Problem[] {
    const clean = this.makeTextComparable(text);
    const found = [...CLICHES, ...FILLER].filter((phrase) => this.containsPhrase(clean, phrase));
    if (found.length === 0) return [];
    return [this.problem("ai-cliche", "fix", where,
      `Stock or filler phrases: ${found.map((f) => `"${f}"`).join(", ")}.`,
      "Cut them or say the specific thing instead.")];
  }

  /** Too many AI words across the whole book. A few are fixes; many block. */
  private findTooManyAiWords(allText: string, where = "whole book"): Problem[] {
    const { hits, per100 } = this.countAiWords(allText);
    if (hits === 0) return [];
    const tooMany = hits >= AI_WORDS_BLOCK_MIN_HITS && per100 >= AI_WORDS_BLOCK_PER_100;
    return [this.problem("ai-words", tooMany ? "block" : "fix", where,
      `${hits} AI-sounding words (${per100.toFixed(2)} per 100 words), e.g. ${this.firstAiWords(allText).join(", ")}.`,
      "Replace them with plain words: use (not utilize), look at (not delve into), key (not pivotal).")];
  }

  /** The same paragraph twice is a sign of a generation loop. */
  private findRepeatedParagraphs(paragraphs: readonly Paragraph[]): Problem[] {
    const seen = new Map<string, string>();
    const problems: Problem[] = [];
    for (const p of paragraphs) {
      const key = this.makeTextComparable(p.text).replace(/\s+/g, " ").trim();
      if (key.length < 80) continue;
      const first = seen.get(key);
      if (first) problems.push(this.problem("repeated-paragraph", "fix", p.where,
        `This paragraph repeats ${first}.`, "Delete the copy or write something new."));
      else seen.set(key, p.where);
    }
    return problems;
  }

  /** Per-chapter checks: reading ease and sentence rhythm. */
  private checkOneChapter(chapter: ChapterToCheck, audience: Audience): Problem[] {
    const text = chapter.sections.map((s) => this.stripMarkdown(s)).join("\n\n");
    const where = `chapter "${chapter.title}"`;
    return [...this.findHardToRead(text, where, audience), ...this.findSameShapeSentences(text, where)];
  }

  /** Reading ease below the target for this audience. */
  private findHardToRead(text: string, where: string, audience: Audience): Problem[] {
    if (this.splitIntoWords(text).length < 150) return [];
    const ease = this.readingEase(text);
    const target = READING_EASE_TARGET[audience];
    if (ease >= target) return [];
    return [this.problem("hard-to-read", audience === "adult" ? "note" : "fix", where,
      `Reading ease is ${Math.round(ease)}; ${audience} books should reach ${target}.`,
      "Use shorter sentences and plainer words.")];
  }

  /** Every sentence the same length reads like a machine wrote it. */
  private findSameShapeSentences(text: string, where: string): Problem[] {
    const lengths = this.splitIntoSentences(text).map((s) => this.splitIntoWords(s).length);
    if (lengths.length < 20) return [];
    const spread = this.standardDeviation(lengths);
    if (spread >= 4) return [];
    return [this.problem("ai-same-rhythm", "fix", where,
      `Sentence lengths barely change (spread ${spread.toFixed(1)} words).`,
      "Mix short and long sentences, the way people talk.")];
  }

  // ----- step 3: store and listing rules -----

  /** Claims nobody has proven: "#1", "bestseller", search numbers, "fully compliant". */
  private findUnprovenClaims(text: string, where: string): Problem[] {
    const hit = UNPROVEN_CLAIM_PATTERNS.find((pattern) => pattern.test(text));
    if (!hit) return [];
    const match = text.match(hit)?.[0] ?? "";
    return [this.problem("unproven-claim", "fix", where,
      `Unproven claim: "${match}".`, "Remove it, or keep it only with proof you can show the store.")];
  }

  /** Title, subtitle, description and keywords against store rules. */
  private findListingProblems(book: BookToCheck): Problem[] {
    const problems: Problem[] = [];
    const titleLine = `${book.title} ${book.subtitle ?? ""}`.trim();
    if (titleLine.length > STORE_LIMITS.titleAndSubtitleMaxChars) problems.push(this.problem("listing-title-length", "fix", "title",
      `Title and subtitle are ${titleLine.length} characters; the limit is ${STORE_LIMITS.titleAndSubtitleMaxChars}.`, "Shorten the subtitle."));
    const promo = PROMO_WORDS.find((word) => this.containsPhrase(this.makeTextComparable(titleLine), word));
    if (promo) problems.push(this.problem("listing-title-promo", "block", "title",
      `Title or subtitle contains a promotion word ("${promo}").`, "Remove it. Stores reject promotional titles."));
    problems.push(...this.findCoverTitleMismatch(book));
    if ((book.description ?? "").length > STORE_LIMITS.descriptionMaxChars) problems.push(this.problem("listing-description-length", "fix", "description",
      `Description is ${(book.description ?? "").length} characters; the limit is ${STORE_LIMITS.descriptionMaxChars}.`, "Shorten the description."));
    problems.push(...this.findDescriptionProblems(book.description ?? ""));
    problems.push(...this.findKeywordProblems(book));
    problems.push(...this.findOtherStoreNotes(book));
    return problems;
  }

  /** Things KDP does not allow in a description: links, contacts, reviews, prices, dates. */
  private findDescriptionProblems(description: string): Problem[] {
    return DESCRIPTION_FORBIDDEN.filter((rule) => rule.pattern.test(description)).map((rule) =>
      this.problem("description-forbidden", "fix", "description",
        `The description contains ${rule.what}, which KDP does not allow.`, "Remove it from the description."));
  }

  /** Other stores have stricter rules. These are notes so a person can pick the right stores. */
  private findOtherStoreNotes(book: BookToCheck): Problem[] {
    const notes: Problem[] = [];
    if (book.publicDomain) notes.push(this.problem("store-public-domain", "note", "stores",
      "Kobo and Draft2Digital do not accept public-domain works; Google Play Books only accepts them from selected partners.",
      "Publish this book on KDP (and Apple Books) only."));
    if (book.aiGenerated) notes.push(this.problem("store-ai-content", "note", "stores",
      "Kobo rejects books wholly or partly generated by AI. Draft2Digital needs extensive human editing. Apple Books needs the \"AI Generated by\" contributor role.",
      "Have a person rewrite and edit the book, then declare AI use on every store that asks."));
    return notes;
  }

  /** The cover must show the same title as the listing. */
  private findCoverTitleMismatch(book: BookToCheck): Problem[] {
    if (!book.coverText || book.coverText.length === 0) return [];
    const cover = this.makeTextComparable(book.coverText.join(" ")).replace(/\s+/g, " ");
    const title = this.makeTextComparable(book.title).replace(/\s+/g, " ").trim();
    if (cover.includes(title)) return [];
    return [this.problem("listing-cover-title", "fix", "cover",
      "The cover does not show the same title as the listing.", "Make the cover title match the book title exactly.")];
  }

  /** Keyword count, length, promo words and other authors' names. */
  private findKeywordProblems(book: BookToCheck): Problem[] {
    const keywords = book.keywords ?? this.readKeywords(book.metadata ?? "");
    const problems: Problem[] = [];
    if (keywords.length > STORE_LIMITS.keywordsMax) problems.push(this.problem("keywords-count", "fix", "keywords",
      `${keywords.length} keywords; the store allows ${STORE_LIMITS.keywordsMax}.`, "Keep the most useful ones."));
    for (const keyword of keywords) {
      const promo = PROMO_WORDS.find((word) => this.containsPhrase(this.makeTextComparable(keyword), word));
      if (promo) problems.push(this.problem("keyword-promo", "fix", `keyword "${keyword}"`,
        `Keyword contains "${promo}", which stores do not allow.`, "Remove the promo word."));
    }
    return problems;
  }

  /** Any ISBN printed in or on the book must be valid and owned by the author. */
  private findFakeIsbns(book: BookToCheck): Problem[] {
    const places: [string, string][] = [
      ["cover", (book.coverText ?? []).join("\n")], ["description", book.description ?? ""],
      ["metadata", book.metadata ?? ""], ["book text", book.chapters.flatMap((c) => c.sections).join("\n")],
    ];
    const owned = this.onlyDigits(book.isbn ?? "");
    const problems: Problem[] = [];
    for (const [where, text] of places) {
      for (const isbn of this.findIsbnLikeNumbers(text)) {
        if (!this.isValidIsbn(isbn)) problems.push(this.problem("isbn-invalid", "block", where,
          `"${isbn}" is not a valid ISBN (the check digit is wrong).`, "Remove it. Use the ISBN the store gives you, or leave the barcode area blank."));
        else if (this.onlyDigits(isbn) !== owned) problems.push(this.problem("isbn-not-owned", "block", where,
          `ISBN "${isbn}" was not supplied by the author.`, "Remove it. Only print an ISBN you own or one the store assigned to this book."));
      }
    }
    return problems;
  }

  /** AI-made books must say so in the store listing. */
  private findMissingAiDisclosure(book: BookToCheck): Problem[] {
    if (!book.aiGenerated) return [];
    if (book.aiDisclosure?.text) return [];
    return [this.problem("ai-disclosure", "fix", "listing",
      "AI wrote text for this book, but the listing does not declare it.",
      "Declare AI-generated content when you publish (KDP asks for text and images separately).")];
  }

  /** Public-domain adaptations must be clearly different from the original. */
  private findPublicDomainProblems(book: BookToCheck, allText: string): Problem[] {
    if (!book.publicDomain) return [];
    const problems: Problem[] = [];
    const titleLine = this.makeTextComparable(`${book.title} ${book.subtitle ?? ""}`);
    const hasMarker = PUBLIC_DOMAIN_TITLE_MARKERS.some((w) => this.containsPhrase(titleLine, w));
    if (!hasMarker) problems.push(this.problem("public-domain-title", "block", "title",
      'A public-domain book must say "(Annotated)", "(Translated)" or "(Illustrated)" in its title. "Adapted" or "modernized" do not count on KDP.',
      "Add original annotations, an original translation or 10+ original illustrations, and put the matching word in the title."));
    const description = (book.description ?? "").trim();
    if (!/^\s*[-*•]/.test(description)) problems.push(this.problem("public-domain-description", "fix", "description",
      "KDP wants a public-domain description to start with a bullet-point summary of what is original (80 characters max).",
      'Start the description with a line like "• Original annotations on every chapter".'));
    const sourceText = book.publicDomain.sourceText;
    if (sourceText && this.shareCopiedFrom(allText, sourceText) > 0.75) problems.push(this.problem("public-domain-copy", "block", "whole book",
      "Most of the book is copied word for word from the public-domain source.", "Add real new content: translation, commentary, notes or illustrations."));
    return problems;
  }

  // ----- step 4: the report -----

  /** Turn problems into one verdict plus simple numbers. */
  private makeReport(problems: Problem[], text: string): SafetyReport {
    const limited = this.limitExamples(problems);
    const verdict = limited.some((p) => p.level === "block") ? "block"
      : limited.some((p) => p.level === "fix") ? "fix" : "pass";
    const { per100 } = this.countAiWords(text);
    return {
      verdict,
      problems: limited,
      scores: { words: this.splitIntoWords(text).length, readingEase: Math.round(this.readingEase(text)), aiWordsPer100: Number(per100.toFixed(2)) },
    };
  }

  /** Keep at most MAX_EXAMPLES_PER_RULE problems per rule, plus a count of the rest. */
  private limitExamples(problems: Problem[]): Problem[] {
    const perRule = new Map<string, number>();
    const kept: Problem[] = [];
    for (const p of problems) {
      const count = (perRule.get(p.rule) ?? 0) + 1;
      perRule.set(p.rule, count);
      if (count <= MAX_EXAMPLES_PER_RULE) kept.push(p);
    }
    for (const [rule, count] of perRule) {
      if (count > MAX_EXAMPLES_PER_RULE) kept.push(this.problem(rule, "note", "summary", `${count - MAX_EXAMPLES_PER_RULE} more like this were hidden.`, "Fix the ones shown, then check again."));
    }
    return kept;
  }

  /** Build one problem. */
  private problem(rule: string, level: Level, where: string, why: string, howToFix: string): Problem {
    return { rule, level, where, why, howToFix };
  }

  // ----- helpers: text -----

  /**
   * Make text easy to compare against the word lists:
   * same-looking letters become the same letter, emojis become words,
   * hidden characters and art characters go away, and disguises are undone.
   */
  private makeTextComparable(text: string): string {
    let plain = text.normalize("NFKC");
    plain = [...plain].map((ch) => EMOJI_MEANINGS[ch] ?? ch).join("");
    plain = plain.toLowerCase();
    plain = [...plain].map((ch) => LOOK_ALIKE_LETTERS[ch] ?? ch).join("");
    plain = plain.replace(INVISIBLE_CHARACTERS, "").replace(DIRECTION_FLIPPERS, "").replace(ART_CHARACTERS, " ");
    plain = this.joinSpacedOutLetters(plain);
    return plain.split(/(\s+)/).map((piece) => this.undoNumberDisguise(piece)).join("");
  }

  /** "s e x", "s.e.x", "s-e-x" -> "sex". Three or more single letters with one mark between them. */
  private joinSpacedOutLetters(text: string): string {
    return text.replace(/\b(?:[a-z][\s._*-]){2,}[a-z]\b/g, (match) => match.replace(/[\s._*-]/g, ""));
  }

  /** The first letter of every non-empty line, joined: "Fun\nUp\n..." -> "fu...". */
  private firstLetterOfEachLine(text: string): string {
    return text.split("\n").map((line) => this.makeTextComparable(line).trim().match(/[a-z]/)?.[0] ?? "").join("");
  }

  /** Share of sampled pixels that look like skin, and that look like blood red (0 to 1). */
  private countColourShares(image: { width: number; height: number; rgba: ArrayLike<number> }): { skin: number; blood: number } {
    const pixels = image.width * image.height;
    const step = Math.max(1, Math.floor(pixels / 40_000));
    let sampled = 0, skin = 0, blood = 0;
    for (let i = 0; i < pixels; i += step) {
      const r = image.rgba[i * 4] ?? 0, g = image.rgba[i * 4 + 1] ?? 0, b = image.rgba[i * 4 + 2] ?? 0;
      sampled++;
      if (this.looksLikeSkin(r, g, b)) skin++;
      if (r > 140 && g < 50 && b < 50) blood++;
    }
    return { skin: sampled ? skin / sampled : 0, blood: sampled ? blood / sampled : 0 };
  }

  /** Classic skin-colour test in YCbCr colour space (Chai & Ngan, 1999). Rough on purpose. */
  private looksLikeSkin(r: number, g: number, b: number): boolean {
    const cb = 128 - 0.168736 * r - 0.331264 * g + 0.5 * b;
    const cr = 128 + 0.5 * r - 0.418688 * g - 0.081312 * b;
    return cb >= 77 && cb <= 127 && cr >= 133 && cr <= 173;
  }

  /** "s3x" -> "sex", "k1d" -> "kid". Only inside words that also have letters. */
  private undoNumberDisguise(word: string): string {
    if (!/[a-z]/.test(word) || !/[0-9@$]/.test(word)) return word;
    if (/^\d/.test(word) && /year|yr/.test(word)) return word; // keep ages like "12-year-old"
    const swaps: Record<string, string> = { "0": "o", "1": "i", "3": "e", "4": "a", "5": "s", "7": "t", "@": "a", "$": "s" };
    return [...word].map((ch) => swaps[ch] ?? ch).join("");
  }

  /** Turn "12-year-old" and "twelve year old" (under 18) into the word "minorage". */
  private markYoungAges(text: string): string {
    const byNumber = text.replace(/\b(\d{1,2})[- ]?(?:years?|yrs?)[- ]old\b/g, (match, age: string) => (Number(age) < 18 ? " minorage " : match));
    return byNumber.replace(/\b([a-z]+)[- ](?:years?)[- ]old\b/g, (match, age: string) => (YOUNG_AGE_WORDS.includes(age) ? " minorage " : match));
  }

  /** Remove markdown marks so they don't count as words. */
  private stripMarkdown(text: string): string {
    return text.replace(/^#+\s*/gm, "").replace(/[*_`>|]/g, "").replace(/\[([^\]]*)\]\([^)]*\)/g, "$1");
  }

  /** Split text into lowercase words. */
  private splitIntoWords(text: string): string[] {
    return text.toLowerCase().match(/[a-z0-9]+(?:['’-][a-z0-9]+)*/g) ?? [];
  }

  /** Split text into sentences. */
  private splitIntoSentences(text: string): string[] {
    return text.split(/(?<=[.!?])\s+/).map((s) => s.trim()).filter((s) => s.length > 0);
  }

  /** Every paragraph in the book, with a human-readable location. */
  private splitIntoParagraphs(book: BookToCheck): Paragraph[] {
    const paragraphs: Paragraph[] = [];
    book.chapters.forEach((chapter, c) => {
      const blocks = chapter.sections.join("\n\n").split(/\n\s*\n/).map((b) => b.trim()).filter(Boolean);
      blocks.forEach((text, i) => paragraphs.push({ text, where: `chapter ${c + 1} ("${chapter.title}"), paragraph ${i + 1}` }));
    });
    paragraphs.push({ text: `${book.title}\n${book.subtitle ?? ""}`, where: "title" });
    if (book.description) paragraphs.push({ text: book.description, where: "description" });
    for (const [i, text] of (book.coverText ?? []).entries()) paragraphs.push({ text, where: `cover text ${i + 1}` });
    return paragraphs;
  }

  /** True when `text` contains `phrase` as whole words. */
  private containsPhrase(text: string, phrase: string): boolean {
    return this.wholeWordPattern(phrase).test(text);
  }

  /** A cached regular expression that matches `phrase` as whole words. */
  private wholeWordPattern(phrase: string): RegExp {
    let pattern = this.patternCache.get(phrase);
    if (!pattern) {
      const escaped = phrase.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s+");
      pattern = new RegExp(`(?:^|[^a-z0-9])${escaped}(?=$|[^a-z0-9])`, "i");
      this.patternCache.set(phrase, pattern);
    }
    return pattern;
  }

  /** Where in `words` any word from `list` appears (also matches simple plurals). */
  private positionsOf(words: readonly string[], list: readonly string[]): number[] {
    const set = new Set(list);
    const positions: number[] = [];
    words.forEach((word, i) => {
      if (set.has(word) || (word.endsWith("s") && set.has(word.slice(0, -1)))) positions.push(i);
    });
    return positions;
  }

  /** Read the keyword list out of metadata markdown. */
  private readKeywords(metadata: string): string[] {
    const lines = metadata.split("\n");
    const start = lines.findIndex((line) => /keywords?/i.test(line));
    if (start === -1) return [];
    const sameLine = (lines[start] ?? "").replace(/^.*keywords?\W*/i, "").trim();
    if (sameLine) return sameLine.split(/[,;]/).map((k) => k.replace(/[*_`"]/g, "").trim()).filter(Boolean);
    const listed: string[] = [];
    for (const line of lines.slice(start + 1)) {
      const item = line.match(/^\s*(?:[-*]|\d+[.)])\s+(.+)$/);
      if (!item) break;
      listed.push((item[1] ?? "").replace(/[*_`"]/g, "").trim());
    }
    return listed.filter(Boolean);
  }

  // ----- helpers: numbers -----

  /** Count AI words and how many there are per 100 words. */
  private countAiWords(text: string): { hits: number; per100: number } {
    const clean = this.makeTextComparable(text);
    let hits = 0;
    for (const word of AI_WORDS) hits += (clean.match(this.globalWholeWordPattern(word)) ?? []).length;
    const words = this.splitIntoWords(clean).length;
    return { hits, per100: words ? (hits / words) * 100 : 0 };
  }

  /** The first few AI words found, for the report message. */
  private firstAiWords(text: string): string[] {
    const clean = this.makeTextComparable(text);
    return AI_WORDS.filter((word) => this.containsPhrase(clean, word)).slice(0, 5).map((w) => `"${w}"`);
  }

  /** Like `wholeWordPattern`, but finds every match (not cached: global patterns keep state). */
  private globalWholeWordPattern(phrase: string): RegExp {
    const escaped = phrase.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s+");
    return new RegExp(`(?:^|[^a-z0-9])${escaped}(?=$|[^a-z0-9])`, "gi");
  }

  /** Flesch reading ease: 206.835 − 1.015 × words/sentence − 84.6 × syllables/word. */
  private readingEase(text: string): number {
    const words = this.splitIntoWords(text);
    const sentences = Math.max(1, this.splitIntoSentences(text).length);
    if (words.length === 0) return 100;
    const syllables = words.reduce((sum, word) => sum + this.countSyllables(word), 0);
    const ease = 206.835 - 1.015 * (words.length / sentences) - 84.6 * (syllables / words.length);
    return Math.max(0, Math.min(100, ease));
  }

  /** Rough English syllable count (same method as the MisarBlog engine). */
  private countSyllables(word: string): number {
    let w = word.toLowerCase().replace(/[^a-z]/g, "");
    if (w.length <= 3) return 1;
    w = w.replace(/(?:[^laeiouy]es|ed|[^laeiouy]e)$/, "").replace(/^y/, "");
    return (w.match(/[aeiouy]{1,2}/g) ?? []).length || 1;
  }

  /** How spread out a list of numbers is. */
  private standardDeviation(values: readonly number[]): number {
    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    const variance = values.reduce((sum, v) => sum + (v - mean) ** 2, 0) / values.length;
    return Math.sqrt(variance);
  }

  /** Share of the book's 8-word runs that also appear in the source (0 to 1). */
  private shareCopiedFrom(bookText: string, sourceText: string): number {
    const runs = (text: string) => {
      const words = this.splitIntoWords(text);
      const out = new Set<string>();
      for (let i = 0; i + 8 <= words.length; i++) out.add(words.slice(i, i + 8).join(" "));
      return out;
    };
    const book = runs(bookText);
    if (book.size === 0) return 0;
    const source = runs(sourceText);
    let copied = 0;
    for (const run of book) if (source.has(run)) copied++;
    return copied / book.size;
  }

  // ----- helpers: ISBNs and card numbers -----

  /** Keep only digits (and a trailing X for ISBN-10). */
  private onlyDigits(text: string): string {
    return text.toUpperCase().replace(/[^0-9X]/g, "");
  }

  /** Things that look like an ISBN-13 (978/979…) or a labelled ISBN-10. */
  private findIsbnLikeNumbers(text: string): string[] {
    const isbn13 = text.match(/\b97[89][-\s]?(?:\d[-\s]?){9}\d\b/g) ?? [];
    const isbn10 = [...text.matchAll(/\bISBN(?:-10)?:?\s*((?:\d[-\s]?){9}[\dXx])\b/g)].map((m) => m[1] ?? "");
    return [...new Set([...isbn13, ...isbn10].map((s) => s.trim()))];
  }

  /** Check the ISBN check digit (ISBN-10 or ISBN-13). */
  private isValidIsbn(isbn: string): boolean {
    const digits = this.onlyDigits(isbn);
    if (digits.length === 13) return this.isValidIsbn13(digits);
    if (digits.length === 10) return this.isValidIsbn10(digits);
    return false;
  }

  /** ISBN-13: weights 1,3,1,3…; the total must divide by 10. */
  private isValidIsbn13(digits: string): boolean {
    let total = 0;
    for (let i = 0; i < 13; i++) total += Number(digits[i]) * (i % 2 === 0 ? 1 : 3);
    return total % 10 === 0;
  }

  /** ISBN-10: weights 10,9…1 (X means 10); the total must divide by 11. */
  private isValidIsbn10(digits: string): boolean {
    let total = 0;
    for (let i = 0; i < 10; i++) {
      const ch = digits[i] ?? "0";
      const value = ch === "X" ? 10 : Number(ch);
      if (ch === "X" && i !== 9) return false;
      total += value * (10 - i);
    }
    return total % 11 === 0;
  }

  /** 13–19 digit numbers that pass the Luhn check (how card numbers are checked). */
  private findCardNumbers(text: string): string[] {
    const candidates = text.match(/\b(?:\d[ -]?){12,18}\d\b/g) ?? [];
    return candidates.filter((c) => {
      const digits = c.replace(/\D/g, "");
      return !/^97[89]/.test(digits) && this.passesLuhn(digits);
    });
  }

  /** Luhn check: double every second digit from the right; the total must divide by 10. */
  private passesLuhn(digits: string): boolean {
    let total = 0;
    for (let i = 0; i < digits.length; i++) {
      let d = Number(digits[digits.length - 1 - i]);
      if (i % 2 === 1) d = d * 2 > 9 ? d * 2 - 9 : d * 2;
      total += d;
    }
    return total % 10 === 0;
  }
}
